    injectCSS();
    var cols = DATA.cols, rows = DATA.rows, fps = DATA.fps, palette = DATA.palette, frames = DATA.frames;
    var canvas = document.createElement('canvas');
    canvas.className = 'lotus-canvas';
    canvas.setAttribute('role', 'img');
